from pathlib import Path
import json
ids=['DEV-PRED-CONT-NEXT-50178168cc8b3a8e879648db','DEV-PRED-CONT-NEXT-9d4707f66ec86d580643a52c']
roots=[Path.home()/'.local/state/prediction-project-executor',Path.home()/'.local/share/prediction-project-executor']
out=[]
for tid in ids:
    hits=[]
    for root in roots:
        if root.exists():
            for p in root.rglob('*'):
                if p.is_file() and tid in p.name:
                    hits.append(p)
    chunks=[]
    for p in hits[:16]:
        try: txt=p.read_text(errors='replace')
        except Exception: continue
        chunks.append(str(p)+':'+txt[:3500].replace('\n',' ').replace('|','/'))
    out.append(tid+'=>'+' || '.join(chunks))
print('ERROR_CLASS=NORMALIZE_CHAIN_STATUS')
print('ERROR='+' ### '.join(out)[:12000])
raise SystemExit(1)
